// EFAS numaralarının Vapi ayarlarını ve SIP trunk bilgilerini özetler (şifreler gizlenir)
const EFAS = ['+905337436876', '+905337437088', '+908503465993'];
const rakam = (s) => String(s || '').replace(/\D/g, '').slice(-10);
const numaralar = $('Vapi: Telefon Numaraları').all().map((i) => i.json).filter((n) => n && n.id);
const asistanlar = {};
for (const a of $('Vapi: Asistanlar').all().map((i) => i.json)) if (a && a.id) asistanlar[a.id] = a.name;
const kimlikler = $('Vapi: Kimlik Bilgileri').all().map((i) => i.json).filter((c) => c && c.id);
const gizle = (o) => JSON.parse(JSON.stringify(o, (k, v) => (/pass|secret|token|key/i.test(k) ? '***' : v)));
const efasNumaralari = numaralar.filter((n) => EFAS.some((e) => rakam(e) === rakam(n.number || n.sipUri)));
const kullanilanKimlik = new Set(efasNumaralari.map((n) => n.credentialId).filter(Boolean));
return [{ json: {
  numaralar: efasNumaralari.map((n) => ({
    numara: n.number, id: n.id, ad: n.name, saglayici: n.provider, durum: n.status,
    inboundAsistan: n.assistantId ? asistanlar[n.assistantId] || n.assistantId : 'YOK (gelen arama karşılanmaz)',
    squad: n.squadId || '', workflow: n.workflowId || '', sunucu: n.server && n.server.url || '',
    e164Kontrol: n.numberE164CheckEnabled, kimlikId: n.credentialId || '', fallback: n.fallbackDestination || null,
  })),
  bulunamayan: EFAS.filter((e) => !efasNumaralari.some((n) => rakam(n.number || n.sipUri) === rakam(e))),
  sipTrunklar: kimlikler.filter((c) => kullanilanKimlik.has(c.id) || /sip/i.test(c.provider)).map((c) => gizle({
    id: c.id, ad: c.name, saglayici: c.provider, gateways: c.gateways, outboundLeadingPlusEnabled: c.outboundLeadingPlusEnabled,
    techPrefix: c.techPrefix, sipDiversionHeader: c.sipDiversionHeader, sbcConfiguration: c.sbcConfiguration,
    outboundAuthenticationPlan: c.outboundAuthenticationPlan, efasKullaniyor: kullanilanKimlik.has(c.id),
  })),
} }];
